import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十四卦 归妹 雷泽归妹 震上兑下","description":"周易 - 第五十四卦 归妹 雷泽归妹 震上兑下","frontmatter":{"title":"第五十四卦 归妹 雷泽归妹 震上兑下","description":"周易 - 第五十四卦 归妹 雷泽归妹 震上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/055.md","filePath":"zh/classics/zhouyi/055.md"}'),l={name:"zh/classics/zhouyi/055.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="归妹" tabindex="-1">归妹 <a class="header-anchor" href="#归妹" aria-label="Permalink to “归妹”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>征凶，无攸利。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>归妹，天地之大义也。天地不交，而万物不兴，归妹人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽上有雷，归妹；君子以永终知敝。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>归妹以娣，跛能履，征吉。象曰：归 妹以娣，以恒也。跛能履吉，相承也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>眇能视，利幽人之贞。象曰：利幽人之贞，未变常也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>归妹以须，反归以娣。象曰：归妹以须，未当也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>归妹愆期，迟归有时。象曰：愆期之志，有待而行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。象曰：帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>女承筐无实，士刲羊无血，无攸利。象曰：上六无实，承虚筐也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
